<?php
use App\Entities\TenantContext;
use App\Models\Tenant\Website\GalleryAlbumModel;
use App\Models\Tenant\Website\GalleryItemModel;
use CodeIgniter\Test\CIUnitTestCase;
use CodeIgniter\Test\DatabaseTestTrait;
/** Confirms gallery album and item lookups cannot cross tenant context. @internal */
final class WebsitePhase4IsolationTest extends CIUnitTestCase { use DatabaseTestTrait; protected $migrate=true; protected $namespace='App'; public function testGalleryModelsRemainTenantScoped():void{$a=$this->tenant('gallery-a');$b=$this->tenant('gallery-b');$this->context($a,'gallery-a');$media=$this->media();$album=(int)(new GalleryAlbumModel())->insert(['title'=>'A','slug'=>'a','description'=>'A','category'=>'campus','cover_media_id'=>$media],true);$item=(int)(new GalleryItemModel())->insert(['gallery_album_id'=>$album,'media_file_id'=>$media,'caption'=>'A','alt_text'=>'A','status'=>'published'],true);$this->context($b,'gallery-b');$this->assertNull((new GalleryAlbumModel())->find($album));$this->assertNull((new GalleryItemModel())->find($item));} private function tenant(string $slug):int{$this->db->table('tenants')->insert(['school_name'=>$slug,'slug'=>$slug,'status'=>'active']);return (int)$this->db->insertID();} private function context(int $id,string $slug):void{service('tenantContextManager')->set(new TenantContext($id,$slug,'route_slug'));} private function media():int{$this->db->table('media_files')->insert(['tenant_id'=>service('tenantContextManager')->current()->tenantId,'original_name'=>'a.jpg','stored_name'=>'a.jpg','storage_disk'=>'local','storage_path'=>'a.jpg','mime_type'=>'image/jpeg','extension'=>'jpg','size_bytes'=>1,'width'=>1,'height'=>1,'checksum_sha256'=>str_repeat('a',64),'visibility'=>'public','category'=>'gallery_image','derivatives'=>'{}']);return (int)$this->db->insertID();}}
